using System.Collections;
using System.Windows;
using System.Windows.Media;

namespace WorkTrace.App.Shell;

/// <summary>
/// Applies WorkTrace's design ("Refined Neutral", Themes/Theme.xaml) over the Fluent light theme. The Fluent theme
/// builds its brushes from colours resolved once, so the design replaces the brushes themselves (Themes/Palette.xaml,
/// generated by tools/generate_palette.py). Every resource is copied to the top level of the application resources,
/// where it takes precedence over the Fluent dictionaries; standard controls, views and popups then pick it up.
/// </summary>
internal static class ThemeResources
{
    public static void Apply(Application app)
    {
        app.ThemeMode = ThemeMode.Light;
        var theme = (ResourceDictionary)Application.LoadComponent(new Uri("/WorkTrace;component/Themes/Theme.xaml", UriKind.Relative));
        CopyTo(theme, app.Resources);

        // Body font for every window (inherited by all text, including popups and dialogs).
        if (app.Resources["AppFontFamily"] is FontFamily font)
        {
            EventManager.RegisterClassHandler(typeof(Window), FrameworkElement.LoadedEvent, new RoutedEventHandler((sender, _) =>
            {
                if (sender is Window window && !Equals(window.FontFamily, font))
                {
                    window.FontFamily = font;
                }
            }));
        }
    }

    private static void CopyTo(ResourceDictionary source, ResourceDictionary target)
    {
        foreach (var merged in source.MergedDictionaries)
        {
            CopyTo(merged, target);
        }

        foreach (DictionaryEntry entry in source)
        {
            target[entry.Key] = entry.Value;
        }
    }
}
